examples:
id: SC-AC3
acId: AC3
title: "Нельзя купить билет сверх лимита"
actors: { org: { role: organizer }, anna: { role: participant }, boris: { role: participant } }   # поле сценария, не шаг
steps:
  - as: org
  - create: { entity: ticket_type, data: { name: "Стандарт", kind: standard, active: true, capacity: 1, price: 1000 }, save: tt }
  - as: anna
  - callFn: { name: registerTicket, args: { ticketTypeId: $tt.id, streamId: "$seed.stream[0].id", holderName: "Анна Тестова", holderEmail: "user1@example.test" }, save: r1 }
    consent: true
  - expect: { status: ok, fields: { needsPayment: true } }
  - simulate: { connector: yookassa, event: payment.succeeded, data: { ticket: $r1.ticketId } }
  - runWorkflows: {}
  - as: boris
  - callFn: { name: registerTicket, args: { ticketTypeId: $tt.id, streamId: "$seed.stream[0].id", holderName: "Борис Тестов", holderEmail: "user2@example.test" } }
    consent: true
  - expect: { error: SOLD_OUT }
  - as: anna
  - read: { entity: ticket, id: $r1.ticketId }
  - expect: { fields: { status: paid } }
